import type { INestApplication } from '@nestjs/common';
import { EjsEngine } from '@nestvexa/engine-ejs';
import { registerViewEngine } from 'nestvexa';
import { resolve } from 'node:path';

/**
 * Generated by `nestvexa add engine ejs`. Views ending in `.ejs` under
 * views/ render with this adapter (`@Render('pages/home.ejs')`); `.hbs`
 * views keep using the default Handlebars engine.
 */
export const ejsEngine = new EjsEngine({
  root: resolve(process.cwd(), 'views'),
  cache: process.env['NODE_ENV'] === 'production',
  defaultLayout: 'layouts/main',
});

/**
 * Registers the `.ejs` view engine on Express or Fastify. Call before
 * `app.listen()`; dispose the engine on shutdown if you create it per test.
 */
export async function registerEjsEngine(app: INestApplication): Promise<void> {
  await registerViewEngine(app, 'ejs', ejsEngine);
}
